def test_predict_churn_success(sample_payload_19_features):
    """6, 9 & 10. Test predict_churn parses response, probability, and risk level."""
    mock_resp = MagicMock()
    mock_resp.status_code = 200
    mock_resp.json.return_value = {
        "prediction": 1,
        "churn_label": "Yes",
        "churn_probability": 0.8731,
        "risk_level": "High Risk",
    }

    with patch("requests.post", return_value=mock_resp):
        res = predict_churn(sample_payload_19_features, backend_url="http://dummy-host:8000")
        assert res["success"] is True
        data = res["data"]
        assert data["prediction"] == 1
        assert data["churn_label"] == "Yes"
        assert data["risk_level"] == "High Risk"
        # Probability display conversion test (0.8731 -> 87.31%)
        pct_display = f"{data['churn_probability'] * 100:.2f}%"
        assert pct_display == "87.31%"


def test_predict_churn_validation_error_422(sample_payload_19_features):
    """8. Test 422 validation error handling."""
    mock_resp = MagicMock()
    mock_resp.status_code = 422
    mock_resp.json.return_value = {"detail": "Invalid contract format"}

    with patch("requests.post", return_value=mock_resp):
        res = predict_churn(sample_payload_19_features, backend_url="http://dummy-host:8000")
        assert res["success"] is False
        assert res["status_code"] == 422
        assert "Invalid customer input" in res["error_message"]


def test_streamlit_app_compiles():
    """Verify streamlit_app.py has valid python syntax and can be parsed."""
    app_file = CAPSTONE_ROOT / "frontend" / "streamlit_app.py"
    with open(app_file, "r", encoding="utf-8") as f:
        code = f.read()
    compiled = compile(code, str(app_file), "exec")
    assert compiled is not None
